var CheckDuplicateApproval = Class.create();
CheckDuplicateApproval.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    approvalcheck: function() {
        var apprv1 = this.getParameter('sysparm_approver1');
        var apprv2 = this.getParameter('sysparm_approver2');
        var apprv3 = this.getParameter('sysparm_approver3');
        var apprv4 = this.getParameter('sysparm_approver4');
        var apprv5 = this.getParameter('sysparm_approver5');
        var apprv6 = this.getParameter('sysparm_approver6');
        var apprv7 = this.getParameter('sysparm_approver7');
        var apprv8 = this.getParameter('sysparm_approver8');
        var apprv9 = this.getParameter('sysparm_approver9');

        // Build Array for all approvals //
        var apprval = [apprv1, apprv2, apprv3, apprv4, apprv5, apprv6, apprv7, apprv8, apprv9];

        gs.log('apprval: ' + apprval);

        // Remoce Empty elements from Array //
        var arr = apprval.filter(function(e) {
            return e;
        });

        gs.log('arr: ' + arr);

        //	Find Duplicate existed in the Array true/false  //
        var map = {};
        var result = false;
        for (var i = 0; i < arr.length; i++) {
            // check if object contains entry with this element as key
            if (map[arr[i]]) {
                result = true;
                // terminate the loop
                break;
            }
            // add entry in object with the element as key
            map[arr[i]] = true;
        }
        if (result) {
            gs.log('result: ' + 'dulicate');
            return true;
        } else {
            gs.log('result: ' + 'no dulicate');
            return result;
        }

    },

    type: 'populateapprovaltitle'
});
